options.styles:
font-family: 'Space Grotesk', Inter, sans-serif;
color: #d1e1e5;
height: 100%;
.se-mono { font-family: 'IBM Plex Mono', ui-monospace, monospace; }
.se-label { font-family: 'IBM Plex Mono', monospace; font-size: 10.5px; letter-spacing: .16em; text-transform: uppercase; color: #8fa3ad; }
.se-ok { --tone: #6fe2a0; }
.se-heat { --tone: #f0a44a; }
.se-alarm { --tone: #ff5a4d; }
.se-cyan { --tone: #5fe3e8; }
.se-idle { --tone: #5d6b73; }
@keyframes se-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }
@media (prefers-reduced-motion: reduce) { * { animation: none !important; } }

.se-header { display: flex; align-items: center; gap: 18px; height: 100%; padding: 4px 6px; }
.se-header svg { width: 40px; height: 46px; flex: none; filter: drop-shadow(0 0 14px rgba(95,227,232,.25)); }
.se-brand { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.se-brand h1 { margin: 0; font-size: 22px; font-weight: 600; letter-spacing: .01em; color: #e8f6f7; line-height: 1.1; }
.se-brand h1 b { color: #5fe3e8; font-weight: 600; }
.se-brand p { margin: 0; font-family: 'IBM Plex Mono', monospace; font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: #8fa3ad; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.se-nav { margin-left: auto; display: flex; gap: 6px; flex-wrap: nowrap; justify-content: flex-end; }
.se-nav a { font-family: 'IBM Plex Mono', monospace; font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; color: #9db2b8; text-decoration: none; padding: 6px 10px; white-space: nowrap; border: 1px solid rgba(160,190,205,.18); border-radius: 999px; background: rgba(12,16,21,.6); transition: border-color .15s, color .15s; }
.se-nav a:hover { color: #e8f6f7; border-color: rgba(95,227,232,.5); }
.se-nav a[aria-current="page"] { color: #05070a; background: #5fe3e8; border-color: #5fe3e8; font-weight: 500; }
@media (max-width: 900px) { .se-nav { display: none; } }
